import { lazy, Suspense, createElement, useDeferredValue, useEffect, useState } from "react"

const WhatsAppPanel = import.meta.env.DEV
  ? lazy(() => import("./features/whatsapp/WhatsAppPanel").then((module) => ({ default: module.WhatsAppPanel })))
  : null

import { Activity, ArrowLeft, ArrowRight, BarChart3, CheckCircle2, Clock3, Download, ExternalLink, Eye, EyeOff, FileText, Image, KeyRound, LockKeyhole, LogIn, MessageSquareText, RefreshCw, Search, ShieldAlert, ShieldCheck, Smartphone, UserPlus } from 'lucide-react'
import { HashRouter, Link, Navigate, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom'
import { Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { apiRequest } from './api/client.js'
import providedLogo from './assets/cybersos-logo-transparent.png'
import adminLoginIllustration from './assets/admin-login-illustration.png'

const categories = [
  { value:'phishing', title:'Phishing', description:'Mensajes o páginas falsas que se hacen pasar por un banco, empresa o persona para pedir datos.' },
  { value:'fraude/estafa digital', title:'Fraude o estafa digital', description:'Engaños en internet para obtener dinero, productos o información mediante una oferta falsa.' },
  { value:'suplantación', title:'Suplantación de identidad', description:'Alguien usa tu nombre, fotos o una cuenta parecida a la tuya para engañar a otras personas.' },
  { value:'robo o acceso no autorizado a cuenta', title:'Acceso no autorizado', description:'Perdiste el control de una cuenta o alguien entró sin tu permiso.' },
  { value:'robo de información', title:'Robo de información', description:'Se copiaron, publicaron o usaron tus archivos, datos personales o documentos sin autorización.' },
  { value:'amenaza/acoso digital', title:'Amenaza o acoso digital', description:'Recibiste amenazas, insultos repetidos, persecución o contenido que busca intimidarte.' },
  { value:'extorsión cibernética', title:'Extorsión cibernética', description:'Alguien exige dinero, imágenes o acciones a cambio de no divulgar información o causar daño.' },
  { value:'malware', title:'Programa malicioso', description:'Un archivo, enlace o aplicación infectó tu dispositivo, bloqueó archivos o mostró actividad extraña.' },
  { value:'otro', title:'Otro incidente', description:'Tu caso no encaja en las opciones anteriores. Describe lo que ocurrió con el mayor detalle posible.' },
]
const blank = { category:'', description:'', occurred_at:'', occurred_at_is_approximate:false, channel:'', related_information:{}, reporter_name:'', contact_type:'email', contact_value:'' }

function Brand(){ return <Link className="brand brand-lockup" to="/"><img className="brand-mark" src={providedLogo} width="48" height="48" alt="Logo de CyberSOS"/><span>CyberSOS</span></Link> }
function HowItWorksLink(){ const navigate=useNavigate(); function goToSection(event){ event.preventDefault(); navigate('/'); window.setTimeout(()=>document.getElementById('como-funciona')?.scrollIntoView({behavior:'smooth'}),0) } return <a href="/#como-funciona" onClick={goToSection}>Cómo funciona</a> }
function Layout({children}){ return <div className="public-shell"><a className="skip-link" href="#contenido">Saltar al contenido</a><header className="public-header"><Brand/><nav><HowItWorksLink/><Link className="protection-nav-link" to="/proteccion"><ShieldCheck size={16} aria-hidden="true"/>Protección</Link><Link className="public-admin-link" to="/admin/login">Administrador</Link><Link className="button button-small" to="/reportar">Reportar ahora</Link></nav></header>{children}<footer><Brand/><span>Un internet más seguro empieza contigo</span><Link to="/admin/login">Acceso administrativo</Link></footer></div> }

function Home(){
  const steps=[
    {icon:MessageSquareText,title:'Cuéntanos lo ocurrido',text:'Un formulario guiado te ayuda a registrar lo esencial sin crear una cuenta.'},
    {icon:ShieldAlert,title:'Adjunta evidencias',text:'Puedes añadir imágenes ficticias para demostrar cómo se preservará la información.'},
    {icon:CheckCircle2,title:'Recibe tu número',text:'Al finalizar obtienes un identificador único para el seguimiento institucional.'},
  ]
  return <Layout><main id="contenido">
    <section className="hero hero-dynamic">
      <div className="hero-glow hero-glow-one" aria-hidden="true"></div><div className="hero-glow hero-glow-two" aria-hidden="true"></div>
      <div className="hero-copy"><p className="eyebrow"><span className="live-dot"></span>Un internet más seguro empieza contigo</p><h1>Hay problemas<br/>por ahí.<br/><em>Actúa a tiempo.</em></h1><p className="hero-lead">Tu seguridad digital importa. Reporta situaciones de riesgo y recibe orientación para estar más seguro en línea.</p><div className="hero-actions"><Link className="button" to="/reportar">Reportar ahora <ArrowRight size={18}/></Link><Link className="button button-ghost" to="/proteccion"><ShieldCheck size={18}/>Centro de protección</Link><Link className="button button-admin-ghost" to="/admin/login"><LogIn size={18}/>Panel de administrador</Link></div></div>
      <div className="hero-visual" aria-label="Identidad visual de CyberSOS"><div className="hero-shield"><span className="orbit orbit-one"></span><span className="orbit orbit-two"></span><img className="hero-logo" src={providedLogo} alt="Logo CyberSOS"/></div></div>
    </section>
    <section className="process process-modern reference-process" id="como-funciona" aria-label="Cómo funciona"><div className="feature-grid">{steps.map(({icon},index)=><article className="process-card" key={index}><span className="feature-icon">{createElement(icon)}</span><div><h3>{index===0?'Cuenta lo ocurrido':index===1?'Conserva las pruebas':'Recibe tu caso'}</h3><p>{index===0?'Describe la situación de forma segura y confidencial.':index===1?'Adjunta capturas, enlaces y cualquier evidencia.':'Nuestro equipo lo revisa y te guía en los siguientes pasos.'}</p></div></article>)}</div></section>
    <section className="protection-home-cta"><ShieldCheck size={54} aria-hidden="true"/><div><h2>Centro de protección</h2><p>Recursos, guías y herramientas para un entorno digital más seguro.</p></div><Link to="/proteccion" aria-label="Abrir Centro de protección"><ArrowRight size={42}/></Link></section>
  </main></Layout>
}

function ProtectionCenter(){
  const resources=[
    {icon:ShieldAlert,title:'¿Ves un mensaje sospechoso?',text:'No abras enlaces ni descargues archivos. Comprueba el remitente por un canal que ya conozcas y reporta el intento.',tone:'pink'},
    {icon:LockKeyhole,title:'Protege tus cuentas',text:'Usa contraseñas únicas, activa la verificación en dos pasos y revisa las sesiones abiertas con frecuencia.',tone:'lime'},
    {icon:Smartphone,title:'Si tu dispositivo se comporta raro',text:'Desconéctalo de internet, no introduzcas más claves y pide ayuda técnica antes de borrar evidencias.',tone:'violet'},
  ]
  return <Layout><main id="contenido" className="protection-page"><section className="protection-hero"><div><p className="eyebrow">Centro de protección</p><h1>Pequeñas acciones. <span>Más seguridad.</span></h1><p>Encuentra orientación organizada para actuar ante riesgos digitales, conservar evidencias y reportar un incidente.</p><div className="protection-actions"><Link className="button" to="/reportar">Reportar un incidente <ArrowRight size={18}/></Link><a className="text-link" href="#menus-proteccion">Ver categorías</a></div></div><div className="protection-emblem" aria-hidden="true"><span className="protection-orbit protection-orbit-one"></span><span className="protection-orbit protection-orbit-two"></span><img src={providedLogo} alt=""/><span>PROTEGE<br/>TUS DATOS</span></div></section><section className="protection-menus" id="menus-proteccion"><p className="eyebrow">Centro de protección</p><h2>Elige una categoría</h2><p className="protection-intro">Abre solo la sección que necesitas. Así encontrarás la información sin recorrer toda la página.</p><details className="protection-menu" open><summary><span className="menu-icon"><ShieldAlert size={22}/></span><span><strong>Guía rápida</strong><small>Qué hacer para reducir el riesgo ahora</small></span></summary><div className="protection-menu-content"><div className="protection-grid">{resources.map(({icon,title,text,tone})=><article className={`protection-card ${tone}`} key={title}><span className="protection-icon">{createElement(icon,{'aria-hidden':true})}</span><h3>{title}</h3><p>{text}</p></article>)}</div></div></details><details className="protection-menu"><summary><span className="menu-icon"><LockKeyhole size={22}/></span><span><strong>Seguridad y herramientas</strong><small>Pasos urgentes, test, guías y checklist</small></span></summary><div className="protection-menu-content"><ProtectionExtras/></div></details><details className="protection-menu"><summary><span className="menu-icon"><ExternalLink size={22}/></span><span><strong>Recursos oficiales</strong><small>Ayuda externa y canales de orientación</small></span></summary><div className="protection-menu-content official-resources"><div><h2>Recursos oficiales</h2><p>CyberSOS orienta y recibe reportes; no reemplaza un antivirus, un banco ni a las autoridades.</p></div><div className="resource-links"><a href="https://support.microsoft.com/es-es/windows/seguridad-de-windows-2ae0363d-0ada-4f7e-9aaf-3d0f5a4d6d4e" target="_blank" rel="noreferrer">Seguridad de Windows <ExternalLink size={15}/></a><a href="https://www.incibe.es/ciudadania" target="_blank" rel="noreferrer">Consejos de INCIBE <ExternalLink size={15}/></a></div></div></details></section></main></Layout>
}

function ProtectionExtras(){
  const [risk,setRisk]=useState(false); const [answers,setAnswers]=useState({}); const [shared,setShared]=useState(false)
  const guides=[['Phishing','No respondas ni abras enlaces. Entra al sitio oficial escribiendo la dirección manualmente.'],['Robo de WhatsApp','Solicita un nuevo código solo desde la aplicación oficial y avisa a tus contactos por otro medio.'],['Extorsión','No pagues ni negocies bajo presión. Conserva mensajes, números, perfiles y fechas.'],['Malware','Desconecta el equipo de internet, no introduzcas claves y busca asistencia técnica confiable.'],['Fraude bancario','Contacta inmediatamente a tu banco desde su número oficial y solicita el bloqueo preventivo.']]
  const questions=[['¿Compartiste una contraseña o código?','Cambia la contraseña desde un dispositivo confiable y cierra las sesiones abiertas. Nunca compartas códigos de verificación.'],['¿Perdiste dinero?','Contacta al banco o plataforma usando sus canales oficiales y conserva el comprobante de la transacción.'],['¿Debo borrar los mensajes?','No. Guarda capturas, enlaces, nombres de usuario, números y fechas para conservar la evidencia.']]
  const completed=Object.keys(answers).length; const download=()=>{const content='CHECKLIST CYBERSOS\n\n[ ] Cambié contraseñas comprometidas\n[ ] Activé verificación en dos pasos\n[ ] Contacté al banco por un canal oficial\n[ ] Guardé capturas, enlaces y fechas\n[ ] Reporté el incidente\n'; const blob=new Blob([content],{type:'text/plain;charset=utf-8'}); const url=URL.createObjectURL(blob); const link=document.createElement('a'); link.href=url; link.download='checklist-cybersos.txt'; link.click(); URL.revokeObjectURL(url)}
  const share=async()=>{if(navigator.share){await navigator.share({title:'Centro de protección CyberSOS',text:'Recomendaciones para protegerse de ciberestafas.',url:window.location.href}).catch(()=>null)}else{await navigator.clipboard?.writeText(window.location.href);setShared(true)}}
  return <><section className="risk-section"><div><p className="eyebrow">¿Estás en riesgo ahora?</p><h2>Actúa en este orden</h2><p>Desconecta el equipo si es necesario, cambia claves desde un dispositivo confiable y guarda las evidencias.</p></div><button className="button risk-button" onClick={()=>setRisk(value=>!value)} aria-expanded={risk}>{risk?'Ocultar pasos':'Ver pasos urgentes'}</button>{risk&&<ol className="risk-steps"><li>Detén la conversación y no envíes más códigos ni dinero.</li><li>Contacta a tu banco o plataforma por su canal oficial.</li><li>Guarda capturas y presenta el reporte en CyberSOS y el canal oficial correspondiente.</li></ol>}</section><section className="security-test"><div className="section-heading"><div><p className="eyebrow">Test rápido</p><h2>¿Qué tan expuesto estás?</h2></div><p>{completed}/3 respuestas completadas</p></div><div className="progress-track" aria-label={`Progreso ${completed} de 3`}><span style={{width:`${completed/3*100}%`}}></span></div><div className="test-options">{[['password','¿Reutilizas una contraseña en varias cuentas?'],['twofactor','¿Tienes activada la verificación en dos pasos?'],['evidence','¿Guardas evidencias antes de borrar mensajes?']].map(([id,label])=><label key={id} className="test-option"><input type="checkbox" checked={Boolean(answers[id])} onChange={event=>setAnswers({...answers,[id]:event.target.checked})}/><span>{label}</span></label>)}</div><p className="test-result">{completed===3?'Buen nivel de preparación. Mantén estas prácticas activas.':completed?'Vas avanzando. Completa las acciones que faltan.':'Empieza por activar la verificación en dos pasos y usar contraseñas únicas.'}</p></section><section className="guides-section"><div className="section-heading"><div><p className="eyebrow">Guías por situación</p><h2>Elige tu caso</h2></div><p>Consejos breves para actuar sin perder evidencias.</p></div><div className="guide-list">{guides.map(([title,text])=><details key={title}><summary>{title}</summary><p>{text}</p><Link to="/reportar">Reportar este tipo de incidente <ArrowRight size={15}/></Link></details>)}</div></section><section className="tools-section"><div><p className="eyebrow">Herramientas</p><h2>Llévate esta guía</h2><p>Descarga una lista sencilla o compártela con alguien que necesite ayuda.</p></div><div className="tools-actions"><button className="button button-secondary" onClick={download}>Descargar checklist</button><button className="button button-ghost" onClick={share}>Compartir guía</button>{shared&&<small role="status">Enlace copiado.</small>}</div></section><section className="faq-section"><p className="eyebrow">Preguntas frecuentes</p><h2>Respuestas rápidas</h2>{questions.map(([question,answer])=><details key={question}><summary>{question}</summary><p>{answer}</p></details>)}</section></>
}

function Report(){
  const navigate=useNavigate(); const [step,setStep]=useState(0); const [data,setData]=useState(blank); const [files,setFiles]=useState([]); const [website,setWebsite]=useState(''); const [error,setError]=useState(''); const [loading,setLoading]=useState(false); const names=['Incidente','Detalles','Información','Evidencias','Contacto','Revisión']; const set=(k,v)=>setData(x=>({...x,[k]:v}))
  function next(){ const message=step===0&&!data.category?'Selecciona una categoría.':step===1&&data.description.trim().length<20?'Escribe al menos 20 caracteres.':step===4&&(!data.reporter_name.trim()||!data.contact_value.trim())?'Completa nombre y contacto.':''; if(message)return setError(message); setError(''); setStep(step+1) }
  async function send(){ setLoading(true); setError(''); const body=new FormData(); body.append('payload',JSON.stringify({...data,occurred_at:data.occurred_at||null})); body.append('website',website); files.forEach(f=>body.append('evidence',f)); try{ const result=await apiRequest('/v1/reports',{method:'POST',body}); navigate('/reporte/confirmacion',{state:result}) }catch(error){ setError(error.message||'No pudimos enviar el reporte. Revisa los datos e inténtalo nuevamente.') }finally{ setLoading(false) } }
  return <Layout><main className="report-shell"><div className="report-heading"><Link to="/"><ArrowLeft size={18}/>Volver</Link><p className="eyebrow">Nuevo reporte</p><h1>Cuéntanos qué ocurrió</h1><p>Paso {step+1} de 6</p></div><ol className="stepper">{names.map((n,i)=><li key={n} className={i<=step?'active':''}><span>{i<step?'✓':i+1}</span><small>{n}</small></li>)}</ol><section className="form-card" aria-live="polite">
    {step===0&&<div><h2>¿Qué tipo de incidente quieres reportar?</h2><p className="category-help">Elige la opción que más se parezca a tu caso. No necesitas conocer los términos técnicos.</p><div className="option-grid">{categories.map(({value,title,description})=><button type="button" className={data.category===value?'option selected':'option'} onClick={()=>set('category',value)} aria-pressed={data.category===value} key={value}><strong>{title}</strong><span>{description}</span></button>)}</div></div>}
    {step===1&&<div><h2>Describe lo ocurrido</h2><label>Descripción<textarea rows="7" value={data.description} onChange={e=>set('description',e.target.value)}/></label><div className="two-columns"><label>Fecha y hora<input type="datetime-local" value={data.occurred_at} onChange={e=>set('occurred_at',e.target.value)}/></label><label>Medio utilizado<input value={data.channel} onChange={e=>set('channel',e.target.value)} placeholder="Correo, red social..."/></label></div><label className="check"><input type="checkbox" checked={data.occurred_at_is_approximate} onChange={e=>set('occurred_at_is_approximate',e.target.checked)}/>La fecha es aproximada</label></div>}
    {step===2&&<div><h2>Información relacionada</h2><p>No escribas contraseñas ni códigos.</p><label>Usuario, enlace o número<textarea rows="5" value={data.related_information.notes||''} onChange={e=>set('related_information',{notes:e.target.value})}/></label></div>}
    {step===3&&<div><h2>Adjunta evidencias</h2><div className="drop-zone"><FileText/><strong>Hasta cinco imágenes</strong><span>PNG, JPEG o WebP</span><input type="file" accept="image/png,image/jpeg,image/webp" multiple onChange={e=>setFiles([...e.target.files].slice(0,5))}/></div>{files.map(f=><p className="file-row" key={f.name}>{f.name}<span>{Math.round(f.size/1024)} KB</span></p>)}</div>}
    {step===4&&<div><h2>Información de contacto</h2><label>Nombre completo<input value={data.reporter_name} onChange={e=>set('reporter_name',e.target.value)}/></label><div className="two-columns"><label>Medio<select value={data.contact_type} onChange={e=>set('contact_type',e.target.value)}><option value="email">Correo</option><option value="phone">Teléfono</option></select></label><label>Dato de contacto<input type={data.contact_type==='email'?'email':'tel'} value={data.contact_value} onChange={e=>set('contact_value',e.target.value)}/></label></div></div>}
    {step===5&&<div><h2>Revisa antes de enviar</h2><div className="review-list"><span><small>Categoría</small><strong>{data.category}</strong></span><span><small>Descripción</small><strong>{data.description}</strong></span><span><small>Contacto</small><strong>{data.reporter_name} · {data.contact_value}</strong></span></div><p className="notice">Evita incluir contraseñas, códigos de seguridad o datos bancarios completos.</p></div>}
    <div aria-hidden="true" className="bot-trap"><label>Website<input tabIndex="-1" autoComplete="off" value={website} onChange={e=>setWebsite(e.target.value)}/></label></div>{error&&<p className="form-error">{error}</p>}<div className="form-actions"><button className="button button-ghost" disabled={step===0} onClick={()=>setStep(step-1)}>Anterior</button>{step<5?<button className="button" onClick={next}>Continuar</button>:<button className="button" disabled={loading} onClick={send}>{loading?'Enviando…':'Enviar reporte'}</button>}</div>
  </section></main></Layout>
}

function Confirmation(){ const {state}=useLocation(); const [copied,setCopied]=useState(false); if(!state?.case_number)return <Navigate to="/"/>; async function copyCaseNumber(){try{await navigator.clipboard?.writeText(state.case_number);setCopied(true);window.setTimeout(()=>setCopied(false),3000)}catch{setCopied(false)}} return <Layout><main className="confirmation"><div className="success-icon"><CheckCircle2/></div><p className="eyebrow">Reporte recibido</p><h1>Gracias por dar este paso.</h1><p>Guarda este número como referencia.</p><button type="button" className="case-number" onClick={copyCaseNumber} aria-label="Copiar número de caso"><span>{state.case_number}</span></button>{copied&&<small className="copy-feedback" role="status">Número de caso copiado.</small>}<div className="official-next-step"><strong>¿Necesitas hacer una denuncia formal?</strong><p>CyberSOS es un canal de orientación complementario. Para iniciar una denuncia oficial en Colombia, usa el canal de la Policía o la Fiscalía.</p><div><a href="https://caivirtual.policia.gov.co/denuncie" target="_blank" rel="noreferrer">CAI Virtual <ExternalLink size={15}/></a><a href="https://adenunciar.policia.gov.co/Adenunciar/default.aspx" target="_blank" rel="noreferrer">ADenunciar <ExternalLink size={15}/></a></div></div><Link className="button" to="/">Volver al inicio</Link></main></Layout> }

function PasswordField({id,label,value,onChange,visible,onToggle,autoComplete='new-password'}){
  return <label htmlFor={id}>{label}<span className="password-field"><input id={id} type={visible?'text':'password'} autoComplete={autoComplete} value={value} onChange={onChange}/><button type="button" onClick={onToggle} aria-label={visible?`Ocultar ${label.toLowerCase()}`:`Mostrar ${label.toLowerCase()}`}>{visible?<EyeOff aria-hidden="true"/>:<Eye aria-hidden="true"/>}</button></span></label>
}

function AdminLogin(){
  const navigate=useNavigate(); const location=useLocation(); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [visible,setVisible]=useState(false); const [error,setError]=useState(location.state?.message||''); const [loading,setLoading]=useState(false)
  async function submit(e){e.preventDefault();setLoading(true);setError('');try{await apiRequest('/v1/auth/login',{method:'POST',body:JSON.stringify({email,password})});navigate('/admin')}catch(err){setError(err.message||'Credenciales incorrectas o cuenta aún no activada')}finally{setLoading(false)}}
  return <main className="admin-auth admin-login-page"><section className="login-art" aria-label="Ilustración de seguridad digital"><Brand/><div className="login-art-heading"><span aria-hidden="true"></span><h2>Protección digital<br/>cuando más importa.</h2></div><img src={adminLoginIllustration} alt="Baliza de emergencia protegida por una red digital"/><div className="login-art-orbit" aria-hidden="true"><i></i><i></i><i></i></div><div className="login-art-status"><span className="live-dot" aria-hidden="true"></span><div><small>Canal institucional</small><strong>Reportes protegidos</strong></div><b aria-hidden="true">01</b></div><div className="login-art-copy"><p>Centro de respuesta CyberSOS</p><small>Canal institucional para gestionar ciberdenuncias con confidencialidad.</small></div></section><section className="login-form-area"><form className="auth-card" onSubmit={submit}><span className="icon-tile"><LogIn aria-hidden="true"/></span><p className="eyebrow">Administración institucional</p><h1>Acceso seguro al panel administrativo</h1><p>Gestiona reportes, usuarios y contenidos de forma segura.</p><label htmlFor="admin-email">Correo electrónico<input id="admin-email" type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} placeholder="administrador@institucion.edu" required/></label><PasswordField id="admin-password" label="Contraseña" value={password} onChange={e=>setPassword(e.target.value)} visible={visible} onToggle={()=>setVisible(value=>!value)} autoComplete="current-password"/>{error&&<p className="form-error" role="alert">{error}</p>}<button className="button" disabled={loading}>{loading?'Verificando…':'Iniciar sesión'} <ArrowRight size={17}/></button><Link className="auth-back-link" to="/admin/crear-cuenta">¿Primera vez? Crear cuenta administrativa</Link><Link className="auth-back-link" to="/admin/recuperar">¿Olvidaste tu contraseña?</Link><div className="auth-divider"><span>Activación protegida</span></div><div className="mfa-note"><p className="login-security-note"><ShieldCheck aria-hidden="true"/>El código de verificación se solicita una sola vez.</p><small>Después de activar la cuenta, entra solo con tu correo y contraseña.</small></div></form></section></main>
}

function AgentReport(){
  const navigate=useNavigate(); const [conversationId,setConversationId]=useState(null); const [messages,setMessages]=useState([{role:'assistant',content:'Hola. Soy el asistente de CyberSOS. Cuéntame con tus propias palabras qué ocurrió. No compartas contraseñas, códigos de verificación ni datos bancarios completos.'}]); const [input,setInput]=useState(''); const [draft,setDraft]=useState(null); const [name,setName]=useState(''); const [contact,setContact]=useState(''); const [loading,setLoading]=useState(false); const [error,setError]=useState('');
  async function sendMessage(event){event.preventDefault();const content=input.trim();if(!content||loading)return;const next=[...messages,{role:'user',content}];setMessages(next);setInput('');setLoading(true);setError('');try{const result=await apiRequest('/v1/agent/chat',{method:'POST',body:JSON.stringify({conversation_id:conversationId,messages:next})});setConversationId(result.conversation_id);setMessages(current=>[...current,{role:'assistant',content:result.message}]);setDraft(result.draft)}catch(err){setError(err.message||'El asistente no pudo responder.');}finally{setLoading(false)}}
  async function confirm(){if(!draft?.summary||name.trim().length<2||contact.trim().length<3)return setError('Completa tu nombre y un medio de contacto antes de confirmar.');setLoading(true);setError('');const body=new FormData();body.append('payload',JSON.stringify({category:draft.category||'otro',description:draft.summary,occurred_at:null,occurred_at_is_approximate:false,channel:'Conversación con agente IA',related_information:{facts:draft.facts,missing_information:draft.missing_information,evidence_requested:draft.evidence_requested,ai_assisted:true},reporter_name:name,contact_type:contact.includes('@')?'email':'phone',contact_value:contact}));try{const result=await apiRequest('/v1/reports',{method:'POST',body});navigate('/reporte/confirmacion',{state:result})}catch(err){setError(err.message||'No pudimos registrar el reporte.')}finally{setLoading(false)}}
  return <Layout><main className="report-shell agent-shell"><div className="report-heading"><Link to="/"><ArrowLeft size={18}/>Volver</Link><p className="eyebrow">Asistente CyberSOS</p><h1>Cuéntame qué ocurrió</h1><p>Habla con libertad. El agente organizará la información y te mostrará un resumen antes de registrar el caso.</p></div><section className="agent-card"><div className="agent-messages" aria-live="polite">{messages.map((message,index)=><div className={`agent-message ${message.role}`} key={`${message.role}-${index}`}><strong>{message.role==='assistant'?'CyberSOS':'Tú'}</strong><p>{message.content}</p></div>)}{loading&&<div className="agent-message assistant"><strong>CyberSOS</strong><p>Estoy revisando la información…</p></div>}</div><form className="agent-composer" onSubmit={sendMessage}><label htmlFor="agent-input" className="sr-only">Escribe tu mensaje</label><textarea id="agent-input" rows="3" value={input} onChange={e=>setInput(e.target.value)} placeholder="Por ejemplo: recibí un mensaje extraño y perdí el acceso a mi cuenta…" disabled={loading}/><button className="button" disabled={loading||!input.trim()}>{loading?'Procesando…':'Enviar mensaje'} <ArrowRight size={17}/></button></form>{draft?.summary&&<div className="agent-draft"><p className="eyebrow">Borrador del reporte</p><h2>Revisa la información</h2><p>{draft.summary}</p>{draft.facts?.length>0&&<ul>{draft.facts.map((fact,index)=><li key={index}>{fact}</li>)}</ul>}<label>Nombre completo<input value={name} onChange={e=>setName(e.target.value)} placeholder="Tu nombre"/></label><label>Correo o teléfono<input value={contact} onChange={e=>setContact(e.target.value)} placeholder="medio de contacto"/></label><button type="button" className="button" onClick={confirm} disabled={loading}>Confirmar y registrar reporte <CheckCircle2 size={17}/></button></div>}{error&&<p className="form-error" role="alert">{error}</p>}<p className="notice">No incluyas contraseñas, códigos de seguridad ni datos bancarios completos.</p></section></main></Layout>
}

function AdminPasswordRecovery(){
  const [email,setEmail]=useState(''); const [message,setMessage]=useState(''); const [error,setError]=useState(''); const [loading,setLoading]=useState(false)
  async function submit(e){e.preventDefault();setLoading(true);setError('');try{const result=await apiRequest('/v1/auth/request-password-reset',{method:'POST',body:JSON.stringify({email})});setMessage(result.message)}catch(err){setError(err.message||'No fue posible solicitar la recuperación.')}finally{setLoading(false)}}
  return <main className="admin-auth"><Brand/><form className="auth-card" onSubmit={submit}><span className="icon-tile"><KeyRound/></span><p className="eyebrow">Recuperación segura</p><h1>Restablecer contraseña</h1><p>Escribe el correo administrativo autorizado y recibirás un enlace si la cuenta existe.</p><label htmlFor="recovery-email">Correo electrónico<input id="recovery-email" type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label>{message&&<p className="success-message" role="status">{message}</p>}{error&&<p className="form-error" role="alert">{error}</p>}<button className="button" disabled={loading}>{loading?'Enviando…':'Enviar enlace de recuperación'}</button><Link className="auth-back-link" to="/admin/login"><ArrowLeft/>Volver al inicio de sesión</Link></form></main>
}

function AdminPasswordReset(){
  const navigate=useNavigate(); const [password,setPassword]=useState(''); const [confirmation,setConfirmation]=useState(''); const [error,setError]=useState(''); const [loading,setLoading]=useState(false)
  const params=new URLSearchParams(window.location.hash.slice(1)); const access_token=params.get('access_token')||''; const refresh_token=params.get('refresh_token')||''
  async function submit(e){e.preventDefault();if(password!==confirmation)return setError('Las contraseñas no coinciden.');setLoading(true);setError('');try{await apiRequest('/v1/auth/reset-password',{method:'POST',body:JSON.stringify({access_token,refresh_token,password})});navigate('/admin/login')}catch(err){setError(err.message||'El enlace no es válido o ya venció.')}finally{setLoading(false)}}
  return <main className="admin-auth"><Brand/><form className="auth-card" onSubmit={submit}><span className="icon-tile"><LockKeyhole/></span><p className="eyebrow">Recuperación segura</p><h1>Define una nueva contraseña</h1>{!access_token||!refresh_token?<p className="form-error">El enlace no contiene una sesión válida. Solicita uno nuevo.</p>:<><label>Nueva contraseña<input type="password" autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)} required minLength="6"/></label><label>Confirmar contraseña<input type="password" autoComplete="new-password" value={confirmation} onChange={e=>setConfirmation(e.target.value)} required minLength="6"/></label>{error&&<p className="form-error" role="alert">{error}</p>}<button className="button" disabled={loading}>{loading?'Guardando…':'Guardar nueva contraseña'}</button></>}</form></main>
}

function AdminRegistration(){
  const navigate=useNavigate(); const [form,setForm]=useState({full_name:'',email:'',password:'',password_confirmation:'',setup_key:''}); const [visible,setVisible]=useState(false); const [error,setError]=useState(''); const [loading,setLoading]=useState(false); const update=(name,value)=>setForm(current=>({...current,[name]:value}))
  async function submit(e){e.preventDefault();setError('');if(form.password!==form.password_confirmation)return setError('Las contraseñas deben ser iguales.');setLoading(true);try{const result=await apiRequest('/v1/auth/register-admin',{method:'POST',body:JSON.stringify(form)});navigate('/admin/mfa',{state:result})}catch(err){setError(err.message||'No fue posible crear la cuenta administrativa.')}finally{setLoading(false)}}
  return <main className="admin-auth"><Brand/><form className="auth-card auth-card-wide" onSubmit={submit}><span className="icon-tile"><UserPlus aria-hidden="true"/></span><p className="eyebrow">Activación única</p><h1>Crear cuenta de administrador</h1><p>Esta opción funciona una sola vez y únicamente con el correo previamente autorizado.</p><label htmlFor="admin-full-name">Nombre completo<input id="admin-full-name" autoComplete="name" value={form.full_name} onChange={e=>update('full_name',e.target.value)} required minLength="5"/></label><label htmlFor="registration-email">Correo personal o institucional<input id="registration-email" type="email" autoComplete="email" value={form.email} onChange={e=>update('email',e.target.value)} required placeholder="nombre@correo.com"/></label><PasswordField id="registration-password" label="Contraseña" value={form.password} onChange={e=>update('password',e.target.value)} visible={visible} onToggle={()=>setVisible(value=>!value)}/><PasswordField id="registration-confirmation" label="Confirmar contraseña" value={form.password_confirmation} onChange={e=>update('password_confirmation',e.target.value)} visible={visible} onToggle={()=>setVisible(value=>!value)}/><label htmlFor="admin-setup-key">Clave de creación<span className="input-with-icon"><KeyRound aria-hidden="true"/><input id="admin-setup-key" type="password" autoComplete="off" value={form.setup_key} onChange={e=>update('setup_key',e.target.value)} required aria-describedby="setup-key-help"/></span></label><small id="setup-key-help" className="field-help">Pega la clave local entregada para activar al único administrador.</small>{error&&<p className="form-error" role="alert">{error}</p>}<button className="button" disabled={loading}>{loading?'Creando acceso…':'Crear cuenta y configurar MFA'}</button><Link className="auth-back-link" to="/admin/login"><ArrowLeft aria-hidden="true"/>Volver al inicio de sesión</Link></form></main>
}
function AdminActivation(){
  const navigate=useNavigate(); const [password,setPassword]=useState(''); const [confirmation,setConfirmation]=useState(''); const [error,setError]=useState(''); const [loading,setLoading]=useState(false)
  const [invitation]=useState(()=>{const params=new URLSearchParams(window.location.hash.slice(1));return {access_token:params.get('access_token')||'',refresh_token:params.get('refresh_token')||'',error:params.get('error_description')||''}})
  useEffect(()=>{window.history.replaceState({},'', '/admin/activar')},[])
  async function submit(e){e.preventDefault();if(password.length<12)return setError('Usa al menos 12 caracteres.');if(password!==confirmation)return setError('Las contraseñas no coinciden.');setLoading(true);setError('');try{const result=await apiRequest('/v1/auth/activate',{method:'POST',body:JSON.stringify({access_token:invitation.access_token,refresh_token:invitation.refresh_token,password})});navigate('/admin/mfa',{state:result})}catch(err){setError(err.message||'La invitación no es válida o ya venció.')}finally{setLoading(false)}}
  const invalid=invitation.error||!invitation.access_token||!invitation.refresh_token
  return <main className="admin-auth"><Brand/><form className="auth-card" onSubmit={submit}><span className="icon-tile"><ShieldCheck/></span><p className="eyebrow">Activación segura</p><h1>Configura tu acceso</h1>{invalid?<><p className="form-error">{invitation.error||'El enlace no contiene una sesión válida.'}</p><p>Solicita una invitación nueva y abre únicamente el enlace más reciente.</p><Link className="button" to="/admin/login">Volver al inicio de sesión</Link></>:<><p>Define una contraseña exclusiva para CyberSOS. Después configurarás el segundo factor.</p><label>Nueva contraseña<input type="password" autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)}/></label><label>Confirmar contraseña<input type="password" autoComplete="new-password" value={confirmation} onChange={e=>setConfirmation(e.target.value)}/></label>{error&&<p className="form-error">{error}</p>}<button className="button" disabled={loading}>{loading?'Activando…':'Guardar y configurar MFA'}</button></>}</form></main>
}
function AdminMfa(){ const navigate=useNavigate(); const {state}=useLocation(); const [code,setCode]=useState(''); const [error,setError]=useState(''); async function submit(e){e.preventDefault();try{await apiRequest('/v1/auth/mfa/verify',{method:'POST',body:JSON.stringify({code,email:state?.email||undefined})});navigate('/admin')}catch(err){setError(err.message||'Código de verificación incorrecto o vencido')}} return <main className="admin-auth"><Brand/><form className="auth-card" onSubmit={submit}><span className="icon-tile"><LockKeyhole/></span><h1>Confirma la activación de tu cuenta</h1><p>Te enviamos un código al correo administrativo. Solo se solicita durante la creación de la cuenta.</p>{state?.enrollment?.qr_code&&<div className="mfa-enrollment"><p>Escanea este código con Google Authenticator, Microsoft Authenticator o Authy.</p><img src={state.enrollment.qr_code} alt="Código QR para configurar MFA"/><details><summary>No puedo escanearlo</summary><code>{state.enrollment.secret}</code></details></div>}<label>Código enviado al correo (6 a 8 dígitos)<input inputMode="numeric" pattern="[0-9]{6,8}" maxLength="8" autoComplete="one-time-code" value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,''))}/></label>{error&&<p className="form-error">{error}</p>}<button className="button">Verificar e ingresar</button><small>Después de esta activación, inicia sesión únicamente con tu correo y contraseña.</small></form></main> }

function AdminLayout({children}){ const navigate=useNavigate(); async function logout(){ await apiRequest('/v1/auth/logout',{method:'POST'}).catch(()=>null); navigate('/admin/login') } return <div className="admin-shell"><aside><Brand/><p className="admin-nav-label">PANEL ADMINISTRATIVO</p><nav><Link className="active" to="/admin"><BarChart3/>Dashboard</Link><Link to="/admin"><FileText/>Reportes</Link><Link to="/admin/whatsapp"><MessageSquareText/>Recursos</Link></nav><Link className="back-public" to="/"><ArrowLeft/>Volver al sitio</Link><button className="back-public admin-logout" type="button" onClick={logout}><LogIn/>Cerrar sesión</button><div className="admin-profile"><span>AD</span><div><strong>Administrador</strong><small>Sesión protegida con MFA</small></div></div></aside><main>{children}</main></div> }

function AdminWhatsApp(){ return <AdminLayout><header className="admin-top"><div><p className="eyebrow">Canal de desarrollo</p><h1>WhatsApp</h1><p>Solo mensajes nuevos de una cuenta dedicada. Baileys es una integración no oficial.</p></div></header>{WhatsAppPanel?<Suspense fallback={<p>Cargando WhatsApp…</p>}><WhatsAppPanel/></Suspense>:<p>WhatsApp solo está disponible durante el desarrollo local.</p>}</AdminLayout> }
function Dashboard(){
  const navigate=useNavigate(); const [reports,setReports]=useState([]); const [stats,setStats]=useState({total:0,by_status:{}}); const [search,setSearch]=useState(''); const [status,setStatus]=useState(''); const [priority,setPriority]=useState(''); const [error,setError]=useState(''); const [loading,setLoading]=useState(true); const [refreshKey,setRefreshKey]=useState(0); const deferredSearch=useDeferredValue(search)
  useEffect(()=>{let active=true; setLoading(true); const refresh=()=>Promise.all([apiRequest('/v1/admin/reports'),apiRequest('/v1/admin/statistics')]).then(([r,s])=>{if(active){setReports(r.items);setStats(s);setError('')}}).catch((requestError)=>{if(!active)return;if(requestError.status===401){navigate('/admin/login',{replace:true,state:{message:'Tu sesión administrativa venció. Inicia sesión nuevamente.'}});return}setError(requestError.status>=500?'El servicio no pudo actualizar los reportes. Inténtalo nuevamente.':'No fue posible cargar los reportes. Comprueba tu conexión e inténtalo nuevamente.')}).finally(()=>active&&setLoading(false)); refresh(); const timer=window.setInterval(refresh,15000); return()=>{active=false;window.clearInterval(timer)}},[navigate,refreshKey])
  const items=reports.filter(r=>`${r.case_number} ${r.reporter_name} ${r.category}`.toLowerCase().includes(deferredSearch.toLowerCase())&&(!status||r.status===status)&&(!priority||r.priority===priority))
  const statItems=[{label:'Total de casos',value:stats.total,icon:FileText,tone:'blue'},{label:'Nuevos',value:stats.by_status.Nuevo||0,icon:ShieldAlert,tone:'orange'},{label:'En revisión',value:stats.by_status['En revisión']||0,icon:Activity,tone:'purple'},{label:'Atendidos',value:stats.by_status.Atendido||0,icon:CheckCircle2,tone:'green'}]
  const leadingCategories=Object.entries(stats.by_category||{}).slice(0,3)
  const trendData=(stats.trend||[]).map(item=>({ ...item, label:new Date(`${item.date}T00:00:00`).toLocaleDateString('es-CO',{weekday:'short'}).replace('.',''), reportes:item.count }))
  const statusData=['Nuevo','En revisión','Atendido','Cerrado'].map(name=>({name,value:stats.by_status?.[name]||0})).filter(item=>item.value>0)
  const priorityData=['Crítica','Alta','Media','Baja'].map(name=>({name,value:stats.by_priority?.[name]||0})).filter(item=>item.value>0)
  const chartColors=['#8b5cf6','#ec4899','#06b6d4','#f59e0b']
  return <AdminLayout><header className="admin-top admin-top-modern"><div><p className="eyebrow">Centro de operaciones</p><h1>Hola, Administrador</h1><p>Revisa, clasifica y documenta cada incidente desde un solo lugar.</p></div><span className="environment"><span className="live-dot"></span>Actualización automática</span></header>
    {error&&<div className="admin-error" role="alert"><ShieldAlert/><span>{error}</span><Link to="/admin/login">Volver a iniciar sesión</Link></div>}
    <section className="stat-grid admin-stats">{statItems.map(({label,value,icon,tone})=><article className={`stat-${tone}`} key={label}><span className="stat-icon">{createElement(icon)}</span><div><span>{label}</span><strong>{value}</strong><small>Casos registrados</small></div></article>)}</section>
    <section className="insight-grid" aria-label="Indicadores operativos"><article><p className="eyebrow">Tiempo de gestión</p><strong>{stats.average_resolution_hours===null||stats.average_resolution_hours===undefined?'Sin casos cerrados':`${stats.average_resolution_hours} h`}</strong><span>Promedio de casos atendidos o cerrados</span></article><article><p className="eyebrow">Ciberestafas frecuentes</p>{leadingCategories.length?<ol>{leadingCategories.map(([category,count])=><li key={category}><span>{category}</span><strong>{count}</strong></li>)}</ol>:<span>Aún no hay datos para analizar.</span>}</article><article><p className="eyebrow">Por prioridad</p><div className="priority-summary"><span>Crítica <strong>{stats.by_priority?.Crítica||0}</strong></span><span>Alta <strong>{stats.by_priority?.Alta||0}</strong></span><span>Media <strong>{stats.by_priority?.Media||0}</strong></span></div></article></section>
    <section className="analytics-grid" aria-label="Gráficas de reportes"><article className="analytics-card analytics-trend"><div><p className="eyebrow">Últimos siete días</p><h2>Evolución de reportes</h2></div>{trendData.some(item=>item.reportes>0)?<ResponsiveContainer width="100%" height={245}><BarChart data={trendData} margin={{top:12,right:8,left:-24,bottom:0}}><CartesianGrid vertical={false} stroke="#e8edf5"/><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{fill:'#66758a',fontSize:12}}/><YAxis allowDecimals={false} axisLine={false} tickLine={false} tick={{fill:'#66758a',fontSize:12}}/><Tooltip cursor={{fill:'#f1edff'}} formatter={(value)=>[value,'Reportes']} labelFormatter={(value)=>`Día: ${value}`}/><Bar dataKey="reportes" fill="#7c3aed" radius={[8,8,2,2]} maxBarSize={42}/></BarChart></ResponsiveContainer>:<p className="chart-empty">Aquí verás la actividad diaria cuando lleguen reportes.</p>}</article><article className="analytics-card"><div><p className="eyebrow">Estado de atención</p><h2>Casos por estado</h2></div>{statusData.length?<div className="donut-layout"><ResponsiveContainer width="52%" height={205}><PieChart><Pie data={statusData} dataKey="value" nameKey="name" innerRadius={52} outerRadius={78} paddingAngle={4}>{statusData.map((item,index)=><Cell key={item.name} fill={chartColors[index]}/>)}</Pie><Tooltip formatter={(value)=>[value,'Casos']}/></PieChart></ResponsiveContainer><ul className="chart-legend">{statusData.map((item,index)=><li key={item.name}><span style={{background:chartColors[index]}}></span>{item.name}<strong>{item.value}</strong></li>)}</ul></div>:<p className="chart-empty">Aún no hay casos para clasificar.</p>}</article><article className="analytics-card"><div><p className="eyebrow">Nivel de atención</p><h2>Prioridades asignadas</h2></div>{priorityData.length?<div className="donut-layout"><ResponsiveContainer width="52%" height={205}><PieChart><Pie data={priorityData} dataKey="value" nameKey="name" innerRadius={52} outerRadius={78} paddingAngle={4}>{priorityData.map((item,index)=><Cell key={item.name} fill={chartColors[index]}/>)}</Pie><Tooltip formatter={(value)=>[value,'Casos']}/></PieChart></ResponsiveContainer><ul className="chart-legend">{priorityData.map((item,index)=><li key={item.name}><span style={{background:chartColors[index]}}></span>{item.name}<strong>{item.value}</strong></li>)}</ul></div>:<p className="chart-empty">Las prioridades aparecerán al gestionar los casos.</p>}</article></section>
    <section className="table-card admin-table-card"><div className="table-heading admin-table-heading"><div><p className="eyebrow">Bandeja central</p><h2>Reportes recibidos</h2><p>{items.length} caso{items.length===1?'':'s'} visible{items.length===1?'':'s'}</p></div><div className="admin-filters"><label className="search"><Search/><span className="sr-only">Buscar reportes</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Caso, persona o categoría"/></label><label><span className="sr-only">Filtrar por estado</span><select aria-label="Filtrar por estado" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos los estados</option>{['Nuevo','En revisión','Atendido','Cerrado'].map(x=><option key={x}>{x}</option>)}</select></label><label><span className="sr-only">Filtrar por prioridad</span><select aria-label="Filtrar por prioridad" value={priority} onChange={e=>setPriority(e.target.value)}><option value="">Todas las prioridades</option>{['Crítica','Alta','Media','Baja'].map(x=><option key={x}>{x}</option>)}</select></label><button className="button button-ghost button-small refresh-button" type="button" onClick={()=>setRefreshKey(value=>value+1)} disabled={loading}><RefreshCw size={16}/>{loading?'Actualizando…':'Actualizar'}</button></div></div>
      <div className="report-table"><div className="table-row table-header"><span>Caso</span><span>Origen</span><span>Categoría</span><span>Estado</span><span>Prioridad</span><span></span></div>{loading?<div className="admin-loading" aria-live="polite"><span></span><p>Cargando reportes…</p></div>:items.length?items.map(r=><article className="table-row admin-report-row" key={r.id}><div><strong>{r.case_number}</strong><small>{new Date(r.created_at).toLocaleDateString('es-CO',{day:'2-digit',month:'short',year:'numeric'})}</small></div><span className="source-cell">{r.source}</span><span className="category-cell">{r.category}</span><span className="pill"><span></span>{r.status}</span><span className={`priority p-${r.priority.toLowerCase()}`}>{r.priority}</span><Link className="row-action" to={`/admin/reportes/${r.id}`}>Abrir <ArrowRight/></Link></article>):<div className="empty-state"><FileText/><strong>No encontramos reportes</strong><p>Ajusta la búsqueda o el filtro para ver otros casos.</p><button className="button button-ghost" onClick={()=>{setSearch('');setStatus('');setPriority('')}}>Limpiar filtros</button></div>}</div>
    </section></AdminLayout>
}

function Detail(){
  const {id}=useParams(); const navigate=useNavigate(); const [report,setReport]=useState(null); const [note,setNote]=useState(''); const [saving,setSaving]=useState(false); const [message,setMessage]=useState(''); const [error,setError]=useState(''); const [evidenceError,setEvidenceError]=useState(''); const [retryKey,setRetryKey]=useState(0);
  useEffect(()=>{let active=true; setReport(null); setError(''); apiRequest(`/v1/admin/reports/${id}`).then(item=>active&&setReport(item)).catch(requestError=>{if(!active)return;if(requestError.status===401){navigate('/admin/login');return}setError(requestError.status===404?'Este caso ya no existe o no está disponible.':requestError.message||'No fue posible cargar el caso.')});return()=>{active=false}},[id,navigate,retryKey])
  if(!report)return <AdminLayout>{error?<div className="detail-error page-loading" role="alert"><ShieldAlert/><h1>No pudimos abrir el caso</h1><p>{error}</p><div><Link className="button button-ghost" to="/admin"><ArrowLeft/>Volver a reportes</Link><button className="button" type="button" onClick={()=>setRetryKey(value=>value+1)}>Intentar nuevamente</button></div></div>:<div className="admin-loading page-loading"><span></span><p>Cargando el caso…</p></div>}</AdminLayout>
  async function reload(){const updated=await apiRequest(`/v1/admin/reports/${id}`);setReport(updated)}
  async function update(field,value){setSaving(true);setMessage('');setError('');try{await apiRequest(`/v1/admin/reports/${id}`,{method:'PATCH',body:JSON.stringify({[field]:value})});await reload();setMessage('Cambios guardados.')}catch(requestError){setError(requestError.message||'No fue posible guardar los cambios.')}finally{setSaving(false)}}
  async function add(){if(!note.trim())return;setSaving(true);setMessage('');setError('');try{await apiRequest(`/v1/admin/reports/${id}/observations`,{method:'POST',body:JSON.stringify({text:note.trim()})});setNote('');await reload();setMessage('Observación registrada.')}catch(requestError){setError(requestError.message||'No fue posible guardar la observación.')}finally{setSaving(false)}}
  async function openEvidence(evidenceId){setEvidenceError('');try{const result=await apiRequest(`/v1/admin/evidences/${evidenceId}/download-url`,{method:'POST'});window.open(result.url,'_blank','noopener,noreferrer')}catch{setEvidenceError('No fue posible abrir la evidencia. Inténtalo nuevamente.')}}
  return <AdminLayout><header className="admin-top case-header"><div><Link to="/admin"><ArrowLeft size={16}/>Volver a reportes</Link><p className="eyebrow">Detalle del incidente</p><h1>{report.case_number}</h1><p>{report.category} · recibido por {report.source}</p></div><div className="case-controls"><label>Estado<select disabled={saving} value={report.status} onChange={e=>update('status',e.target.value)}>{['Nuevo','En revisión','Atendido','Cerrado'].map(x=><option key={x}>{x}</option>)}</select></label><label>Prioridad<select disabled={saving} value={report.priority} onChange={e=>update('priority',e.target.value)}>{['Baja','Media','Alta','Crítica'].map(x=><option key={x}>{x}</option>)}</select></label></div></header>{error&&<div className="admin-error" role="alert"><ShieldAlert/><span>{error}</span></div>}{message&&<p className="success-message" aria-live="polite"><CheckCircle2/>{message}</p>}
    <div className="detail-grid detail-grid-modern"><section className="detail-card report-overview"><div className="card-title"><span className="card-icon"><FileText/></span><div><p className="eyebrow">Información reportada</p><h2>Descripción del caso</h2></div></div><p className="description">{report.description}</p><dl><div><dt>Persona de contacto</dt><dd>{report.reporter_name}</dd></div><div><dt>Dato de contacto</dt><dd>{report.contact_value}</dd></div><div><dt>Canal del incidente</dt><dd>{report.channel||'No informado'}</dd></div></dl></section>
      <section className="detail-card evidence-card"><div className="card-title"><span className="card-icon"><Image/></span><div><p className="eyebrow">Archivos privados</p><h2>Evidencias</h2></div></div>{evidenceError&&<p className="form-error">{evidenceError}</p>}{report.evidences?.length?<div className="evidence-list">{report.evidences.map(item=><article key={item.id}><span><Image/><span><strong>{item.original_name}</strong><small>{(item.size_bytes/1024).toFixed(1)} KB · enlace válido por 60 segundos</small></span></span><button className="button button-ghost button-small" onClick={()=>openEvidence(item.id)}>Abrir <Download size={16}/></button></article>)}</div>:<p className="inline-empty">Este reporte no tiene evidencias adjuntas.</p>}</section>
      <section className="detail-card observations-card"><div className="card-title"><span className="card-icon"><MessageSquareText/></span><div><p className="eyebrow">Seguimiento interno</p><h2>Observaciones</h2></div></div><label htmlFor="admin-note">Nueva observación<textarea id="admin-note" rows="4" value={note} onChange={e=>setNote(e.target.value)} placeholder="Escribe una nota clara para el historial del caso"/></label><button className="button button-small" disabled={saving||!note.trim()} onClick={add}>{saving?'Guardando…':'Guardar observación'}</button>{report.observations.length?report.observations.map(x=><article className="timeline-item" key={x.id}><MessageSquareText/><div><strong>{x.text}</strong><small>{new Date(x.created_at).toLocaleString('es-CO')}</small></div></article>):<p className="inline-empty">Todavía no hay observaciones.</p>}</section>
      <section className="detail-card history-card"><div className="card-title"><span className="card-icon"><Clock3/></span><div><p className="eyebrow">Trazabilidad</p><h2>Historial del caso</h2></div></div>{report.history.map((x,i)=><article className="timeline-item" key={`${x.created_at}-${i}`}><span></span><div><strong>{x.action}</strong><small>{new Date(x.created_at).toLocaleString('es-CO')}</small></div></article>)}</section>
    </div></AdminLayout>
}

/* eslint-disable no-irregular-whitespace */
function ControlCenter(){
  const navigate=useNavigate(); const [reports,setReports]=useState([]); const [stats,setStats]=useState({total:0,by_status:{},by_priority:{},trend:[]}); const [search,setSearch]=useState(''); const [error,setError]=useState('');
  useEffect(()=>{let active=true; Promise.all([apiRequest('/v1/admin/reports'),apiRequest('/v1/admin/statistics')]).then(([r,s])=>{if(active){setReports(r.items);setStats(s)}}).catch(e=>{if(e.status===401)navigate('/admin/login',{replace:true});else setError('No fue posible cargar los datos del centro de control.')});return()=>{active=false}},[navigate])
  const items=reports.filter(r=>`${r.case_number} ${r.category} ${r.reporter_name}`.toLowerCase().includes(search.toLowerCase())).slice(0,6); const critical=stats.by_priority?.['Crítica']||0; const active=(stats.by_status?.Nuevo||0)+(stats.by_status?.['En revisión']||0); const resolved=(stats.by_status?.Atendido||0)+(stats.by_status?.Cerrado||0); const total=stats.total||0; const risk=[{name:'Críticos',value:critical},{name:'Altos',value:stats.by_priority?.Alta||0},{name:'Medios',value:stats.by_priority?.Media||0},{name:'Bajos',value:stats.by_priority?.Baja||0}].filter(x=>x.value); const trend=(stats.trend||[]).map(x=>({...x,reportes:x.count,label:new Date(`${x.date}T00:00:00`).toLocaleDateString('es-CO',{day:'numeric',month:'short'})}));
  return <AdminLayout><header className="control-header"><div><p className="eyebrow">Operaciones de seguridad</p><h1>Centro de control</h1><p>Monitorea, gestiona y responde ante incidentes de ciberseguridad.</p></div><div className="control-search"><Search size={18}/><input aria-label="Buscar casos" placeholder="Buscar casos, usuarios, recursos…" value={search} onChange={e=>setSearch(e.target.value)}/><span>⌕</span></div></header>{error&&<div className="admin-error" role="alert"><ShieldAlert/><span>{error}</span></div>}<section className="control-kpis"><article><FileText/><span>Casos activos</span><strong>{active}</strong><small>↑ 12% vs. semana anterior</small></article><article><ShieldAlert/><span>Casos críticos</span><strong>{critical}</strong><small>↑ 50% vs. semana anterior</small></article><article><Clock3/><span>En revisión</span><strong>{stats.by_status?.['En revisión']||0}</strong><small>↓ 20% vs. semana anterior</small></article><article><CheckCircle2/><span>Casos resueltos</span><strong>{resolved}</strong><small>↑ 35% vs. semana anterior</small></article></section><section className="control-columns"><article className="control-card priority-table"><div className="control-card-title"><div><h2>Casos prioritarios</h2><p>Casos ordenados por riesgo, impacto y antigüedad.</p></div><Link to="/admin">Ver todos　→</Link></div><div className="control-table-head"><span>ID del caso</span><span>Categoría</span><span>Estado</span><span>Prioridad</span><span>Última actualización</span></div>{items.length?items.map(r=><Link className="control-table-row" to={`/admin/reportes/${r.id}`} key={r.id}><span><strong>{r.case_number}</strong></span><span>{r.category}</span><span className={`control-pill ${r.status==='En revisión'?'review':''}`}>{r.status}</span><span className={`control-pill priority-${r.priority.toLowerCase()}`}>{r.priority}</span><span>{new Date(r.updated_at||r.created_at).toLocaleDateString('es-CO')}</span></Link>):<div className="control-empty">No hay casos prioritarios registrados.</div>}</article><aside className="control-side"><article className="control-card risk-card"><div className="control-card-title"><div><h2>Resumen de riesgo</h2><p>Distribución por nivel de riesgo.</p></div></div>{risk.length?<div className="risk-chart"><ResponsiveContainer width="52%" height={150}><PieChart><Pie data={risk} dataKey="value" innerRadius={42} outerRadius={65} paddingAngle={3}>{risk.map((x,i)=><Cell key={x.name} fill={['#ff00a8','#a600ff','#ffc400','#a6ff00'][i]}/>)}</Pie></PieChart></ResponsiveContainer><div><strong>{total}</strong><span>Total de casos</span></div></div>:<div className="control-empty">Aún no hay datos de riesgo.</div>}</article><article className="control-card activity-card"><h2>Actividad reciente</h2>{items.slice(0,4).map(r=><p key={r.id}><i/>Caso actualizado: <strong>{r.case_number}</strong><small>{r.category}</small></p>)}</article></aside></section><section className="control-bottom"><article className="control-card trend-card"><div className="control-card-title"><div><h2>Evolución de reportes</h2><p>Actividad de los últimos siete días.</p></div></div>{trend.length?<ResponsiveContainer width="100%" height={220}><LineChart data={trend}><CartesianGrid stroke="#303340" vertical={false}/><XAxis dataKey="label" stroke="#aaa6b8"/><YAxis stroke="#aaa6b8" allowDecimals={false}/><Tooltip/><Line type="monotone" dataKey="reportes" stroke="#ff00e6" strokeWidth={3} dot={{fill:'#a6ff00'}}/></LineChart></ResponsiveContainer>:<div className="control-empty">Aquí aparecerá la evolución de los reportes.</div>}</article><article className="control-card quick-card"><h2>Acciones rápidas</h2><button onClick={()=>navigate('/reportar')}>＋ Reportar caso</button><button onClick={()=>navigate('/admin')}>▤ Ver todos los casos</button><button onClick={()=>navigate('/admin')}>▥ Generar informe</button><button onClick={()=>navigate('/proteccion')}>▱ Centro de recursos</button></article></section></AdminLayout>
}

export default function App(){ return <HashRouter><Routes><Route path="/" element={<Home/>}/><Route path="/proteccion" element={<ProtectionCenter/>}/><Route path="/reportar" element={<AgentReport/>}/><Route path="/reportar/formulario" element={<Report/>}/><Route path="/reporte/confirmacion" element={<Confirmation/>}/><Route path="/admin/login" element={<AdminLogin/>}/><Route path="/admin/recuperar" element={<AdminPasswordRecovery/>}/><Route path="/admin/restablecer" element={<AdminPasswordReset/>}/><Route path="/admin/crear-cuenta" element={<AdminRegistration/>}/><Route path="/admin/activar" element={<AdminActivation/>}/><Route path="/admin/mfa" element={<AdminMfa/>}/><Route path="/admin" element={<ControlCenter/>}/><Route path="/admin/whatsapp" element={<AdminWhatsApp/>}/><Route path="/admin/reportes/:id" element={<Detail/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes></HashRouter> }
